/// Applies password encryption to PDFs generated by the content renderer.
///
/// The `pdf` package remains responsible for layout, fonts, tables, and
/// document content. Syncfusion is isolated here to provide AES-256 encryption
/// and PDF permission flags that the content renderer does not implement.
library;

import 'dart:math';
import 'dart:typed_data';

import 'package:syncfusion_flutter_pdf/pdf.dart';

import 'pdf_encryption_exception.dart';

/// Encrypts generated PDFs using AES-256 and restricted user permissions.
class PdfEncryptionService {
  const PdfEncryptionService._();

  static const String _ownerPasswordCharacters =
      'ABCDEFGHJKMNPQRSTVWXYZabcdefghjkmnpqrstvwxyz23456789';
  static const int _minimumPasswordLength = 8;
  static const int _ownerPasswordLength = 32;

  /// Encrypts [rawPdfBytes] with [userPassword] using AES-256.
  ///
  /// Printing is optionally permitted, copying and modification are disabled,
  /// and accessibility copying remains enabled for assistive technology.
  /// The random owner password is internal and is never exposed to the caller.
  static Future<Uint8List> encrypt({
    required Uint8List rawPdfBytes,
    required String userPassword,
    bool allowPrint = true,
  }) async {
    if (userPassword.runes.length < _minimumPasswordLength) {
      throw const PdfEncryptionException(
        'PDF password must be at least 8 characters',
      );
    }
    if (rawPdfBytes.isEmpty) {
      throw const PdfEncryptionException('PDF data is empty');
    }

    PdfDocument? document;
    try {
      document = PdfDocument(inputBytes: rawPdfBytes);
      final permissions =
          (document.security
                ..algorithm = PdfEncryptionAlgorithm.aesx256Bit
                ..userPassword = userPassword
                ..ownerPassword = _generateOwnerPassword())
              .permissions;
      final allowedPermissions = <PdfPermissionsFlags>[
        PdfPermissionsFlags.accessibilityCopyContent,
      ];
      if (allowPrint) {
        allowedPermissions.add(PdfPermissionsFlags.print);
      }
      permissions
        ..clear()
        ..addAll(allowedPermissions);

      return Uint8List.fromList(await document.save());
    } catch (_) {
      throw const PdfEncryptionException('Failed to encrypt PDF');
    } finally {
      document?.dispose();
    }
  }

  static String _generateOwnerPassword() {
    final random = Random.secure();
    return List<String>.generate(
      _ownerPasswordLength,
      (_) =>
          _ownerPasswordCharacters[random.nextInt(
            _ownerPasswordCharacters.length,
          )],
    ).join();
  }
}
